import { createYahooFinanceMcpNodeHandler, createYahooFinanceMcpWebHandler, type YahooFinanceMcpHttpOptions, type YahooFinanceMcpNodeHandler, type YahooFinanceMcpWebHandler } from "yahoo-finance2/mcp/http";
const options: YahooFinanceMcpHttpOptions = { client: { quote: async () => ({ symbol: "CONTROLLED" }) }, path: "/mcp", allowedHosts: ["localhost", "::1"], allowedOrigins: ["https://client.test"], bearerToken: "typed-token", enabledTools: ["quote"] };
const node: YahooFinanceMcpNodeHandler = createYahooFinanceMcpNodeHandler(options);
const web: YahooFinanceMcpWebHandler = createYahooFinanceMcpWebHandler(options);
void node; void web;
// @ts-expect-error bearerToken must remain a string
createYahooFinanceMcpWebHandler({ ...options, bearerToken: 42 });
// @ts-expect-error hostname entries must remain strings
createYahooFinanceMcpNodeHandler({ ...options, allowedHosts: [42] });
